"""Check board FP16 parity and explicit camera teacher-agreement budgets."""
from pathlib import Path
import argparse,hashlib,json
import cv2,numpy as np,onnxruntime as ort
from scipy.stats import spearmanr
ROOT=Path(__file__).resolve().parents[1]
def main():
 p=argparse.ArgumentParser();p.add_argument('--candidate',type=Path,required=True);p.add_argument('--board',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();proof=json.loads((a.candidate/'probe.json').read_text());opts=ort.SessionOptions();opts.intra_op_num_threads=4;original=ort.InferenceSession(str(ROOT/'depth_anything_v2/models/model.onnx'),sess_options=opts,providers=['CPUExecutionProvider']);rows=[]
 for record in proof['validation']:
  stem=Path(record['file']).stem;reference=np.fromfile(a.candidate/'reference'/(stem+'-0.f32'),np.float32).reshape(294,518);got=np.fromfile(a.board/'quality-tensors'/(stem+'-0.f32'),np.float32).reshape(294,518);assert np.isfinite(got).all();row={'file':record['file'],'fp16_onnx_spearman':float(spearmanr(reference.ravel(),got.ravel()).statistic),'max_abs_difference':float(np.max(np.abs(reference-got)))}
  if record['camera_16_9']:
   path=ROOT/'data/prepared/validation/depth_anything_v2'/record['file'];rgb=cv2.cvtColor(cv2.imread(str(path)),cv2.COLOR_BGR2RGB);value=(rgb.astype(np.float32)-np.asarray(proof['mean'],np.float32))/np.asarray(proof['std'],np.float32);teacher=original.run(None,{'images':value.transpose(2,0,1)[None]})[0].reshape(518,518)[113:404];student=got[1:292];fit=np.linalg.lstsq(np.stack([student.ravel(),np.ones(student.size)],axis=1),teacher.ravel(),rcond=None)[0];aligned=student*fit[0]+fit[1];scale=max(1e-6,float(np.percentile(teacher,95)-np.percentile(teacher,5)));gx=np.concatenate([v.ravel() for v in np.gradient(teacher)]);gy=np.concatenate([v.ravel() for v in np.gradient(aligned)]);row.update(teacher_spearman=float(spearmanr(teacher.ravel(),student.ravel()).statistic),affine_normalized_rmse=float(np.sqrt(np.mean((teacher-aligned)**2))/scale),gradient_correlation=float(np.corrcoef(gx,gy)[0,1]))
  rows.append(row)
 correlations=[r['fp16_onnx_spearman'] for r in rows];camera=[r for r in rows if 'teacher_spearman' in r];teacher=[r['teacher_spearman'] for r in camera];errors=[r['affine_normalized_rmse'] for r in camera];edges=[r['gradient_correlation'] for r in camera];report={'rows':rows,'validation_images':len(rows),'camera_images':len(camera),'fp16_onnx_median_spearman':float(np.median(correlations)),'fp16_onnx_minimum_spearman':min(correlations),'camera_teacher_median_spearman':float(np.median(teacher)),'camera_teacher_minimum_spearman':min(teacher),'camera_affine_normalized_rmse_median':float(np.median(errors)),'camera_affine_normalized_rmse_maximum':max(errors),'camera_gradient_correlation_median':float(np.median(edges)),'camera_gradient_correlation_minimum':min(edges),'scope':'FP16 parity on 50 held-out images; camera agreement on 18 frames from one existing camera sequence. No metric-depth or broad-scene accuracy claim.'};report['fp16_reference_pass']=len(rows)==50 and report['fp16_onnx_median_spearman']>=.99 and min(correlations)>=.98;report['camera_teacher_agreement_pass']=len(camera)>=10 and np.median(teacher)>=.98 and min(teacher)>=.95 and np.median(errors)<=.05 and max(errors)<=.1 and np.median(edges)>=.90 and min(edges)>=.80;report['passed']=bool(report['fp16_reference_pass'] and report['camera_teacher_agreement_pass']);a.output.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='rows'}),flush=True)
if __name__=='__main__':main()
